#!/usr/bin/env python3
# usage: python3 add-print-tests.py <scratch copy of src/js_parser, after apply-prototype.py>
# Probe only: appends a test `zz_b1_print` to six test modules. Each prints, for sources with comments between the tokens,
# the records that the module's own tests compare. Run: <test binary> zz_b1_print --nocapture --test-threads=1
# Also makes the backtracker tests of parse_skip_typescript.rs count the comments (the 14th list).
import sys, os, json
root = sys.argv[1]
parts = json.loads('{"parse/wrappers.rs": "\\n    #[test]\\n    fn zz_b1_print() {\\n        let cases: &[(&\'static [u8], &\'static [u8], Loader)] = &[\\n            (b\\"/a.ts\\", b\\"y = x /*a*/ as /*b*/ T /*c*/ ; y = x satisfies T /*d*/ ;\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"y = x /*a*/ ! /*b*/ ; y = (x /*c*/) /*d*/ ; y = <T> /*e*/ x /*f*/ ;\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"let v = ( /*1*/ a /*2*/ ) /*3*/ as /*4*/ T /*5*/ ; let w = b /*6*/ ! /*7*/ . c; let u = < /*8*/ T /*9*/ > /*10*/ d /*11*/ ; let s = e /*12*/ satisfies /*13*/ S /*14*/ ;\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"let u = < /*1*/ T /*2*/ > /*3*/ ( /*4*/ d /*5*/ ) /*6*/ ; let f = < /*7*/ T /*8*/ >( /*9*/ x /*10*/ ) /*11*/ => x;\\", Loader::Ts),\\n            (b\\"/a.tsx\\", b\\"const e = <div /*1*/ >{( /*2*/ a /*3*/ ) /*4*/ as T}</div /*5*/ >;\\", Loader::Tsx),\\n        ];\\n        for &(path, text, loader) in cases {\\n            let case = Case { name: \\"b1\\", path, loader, text, records: &[] };\\n            println!(\\"B1 wrappers {:?}\\\\n{:#?}\\", bstr::BStr::new(text), lint_parse(&case));\\n        }\\n    }\\n}\\n", "parse/generics.rs": "\\n    #[test]\\n    fn zz_b1_print() {\\n        let cases: &[(&\'static [u8], &\'static [u8], Loader)] = &[\\n            (b\\"/a.ts\\", b\\"function f /*a*/ < /*b*/ T /*c*/ > /*d*/ () {} const g = < /*e*/ U /*f*/ > /*g*/ (x: U) => x;\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"class A extends B /*a*/ <T> /*b*/ implements I /*c*/ , J<K> /*d*/ {} class D implements a /*e*/ [ /*f*/ 0 /*g*/ ] /*h*/ {}\\", Loader::Ts),\\n            (b\\"/a.tsx\\", b\\"const e = <Foo /*a*/ < /*b*/ T /*c*/ > /*d*/ a=\\\\\\"1\\\\\\" /*e*/ />;\\", Loader::Tsx),\\n            (b\\"/a.ts\\", b\\"f /*a*/ < /*b*/ T /*c*/ > /*d*/ (x); new C /*e*/ <T> /*f*/ (); let i = f<T> /*g*/ ;\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"/*a*/ interface I /*b*/ <T> /*c*/ { a: 1 } /*d*/ type A /*e*/ <T> /*f*/ = T;\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"class E extends f /*1*/ ( /*2*/ ) /*3*/ < /*4*/ T /*5*/ > /*6*/ {}\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"class D implements a /*1*/ . b /*2*/ () /*3*/ < /*4*/ T> /*5*/ {}\\", Loader::Ts),\\n            (b\\"/a.ts\\", b\\"class E extends f /*1*/ ( /*2*/ ) /*3*/ {} class F extends g /*4*/ {}\\", Loader::Ts),\\n        ];\\n        for &(path, text, loader) in cases {\\n            let case = Case { name: \\"b1\\", path, loader, text, records: &[] };\\n            println!(\\"B1 generics {:?}\\\\n{:#?}\\", bstr::BStr::new(text), lint_parse(&case));\\n        }\\n    }\\n}\\n", "parse/syntax_errors.rs": "\\n    #[test]\\n    fn zz_b1_print() {\\n        let cases: &[&\'static [u8]] = &[\\n            b\\"f< /*2*/ >();\\",\\n            b\\"let x: A< /*1*/ >; let y: B<C, /*3*/ >;\\",\\n            b\\"let x: A | /*c*/ () => void;\\",\\n            b\\"let x: A |    () => void;\\",\\n            b\\"let x: A & /*c*/ new () => void;\\",\\n            b\\"let f = (a): /*c*/ => a;\\",\\n            b\\"let f = (a): /*c*/ ;\\",\\n            b\\"let x: /*c*/ ;\\",\\n        ];\\n        for &text in cases {\\n            let found = first_error(b\\"/a.ts\\", text, Loader::Ts).map(|(code, start, end, message)| (code, start, end, String::from_utf8_lossy(&message).into_owned()));\\n            println!(\\"B1 syntax_errors {:?} {:?}\\", bstr::BStr::new(text), found);\\n        }\\n    }\\n}\\n", "parse/erased_tests.rs": "\\n#[test]\\nfn zz_b1_print() {\\n    let cases: &[&\'static [u8]] = &[\\n        b\\"/*a*/ interface I /*b*/ <T> /*c*/ { a: 1 } /*d*/ x;\\",\\n        b\\"type A /*a*/ <T> /*b*/ = T /*c*/ ; /*d*/ type B = 1 /*e*/\\\\nx;\\",\\n        b\\"declare /*a*/ const v: number /*b*/ ; declare function f(): void /*c*/\\\\ny;\\",\\n        b\\"abstract class C { /*a*/ abstract m(): void /*b*/ ; n(): void /*c*/\\\\n n() {} [k: string]: any /*d*/ ; }\\",\\n        b\\"/*1*/ export /*2*/ declare /*3*/ const /*4*/ a /*5*/ : /*6*/ number /*7*/ ; /*8*/ interface /*9*/ I /*10*/ { } /*11*/ type /*12*/ T /*13*/ = /*14*/ 1 /*15*/ ;\\",\\n        b\\"export // export\\\\ninterface I {}\\\\n// export\\\\ndeclare const x: number;\\",\\n        b\\"/*0*/ @ /*1*/ dec /*2*/ ( /*3*/ ) /*4*/ declare class C {} export /*5*/ @ /*6*/ ( /*7*/ dec /*8*/ ) /*9*/ declare class D {}\\",\\n        b\\"declare /*1*/ module /*2*/ \\\\\\"m\\\\\\" /*3*/ { } /*4*/ declare /*5*/ global /*6*/ { } /*7*/ declare namespace A /*8*/ . /*9*/ B /*10*/ { } export {};\\",\\n        b\\"import /*6*/ type /*7*/ { C } /*8*/ from /*9*/ \\\\\\"y\\\\\\" /*10*/ ; export /*1*/ type /*2*/ { A /*3*/ } /*4*/ from /*5*/ \\\\\\"./a\\\\\\" /*6*/ ; export /*1*/ as /*2*/ namespace /*3*/ Foo /*4*/ ;\\",\\n    ];\\n    for &text in cases {\\n        println!(\\"B1 erased {:?}\\\\n{:#?}\\", bstr::BStr::new(text), lint_parse(b\\"/a.ts\\", text));\\n    }\\n}\\n", "parse/annotation_tests.rs": "\\n#[test]\\nfn zz_b1_print() {\\n    let cases: &[(&\'static [u8], &\'static [u8], Loader)] = &[\\n        (b\\"/a.ts\\", b\\"let x /*a*/ : /*b*/ number /*c*/ = 1; function f(this /*d*/ : /*e*/ T /*f*/, p /*g*/ ? /*h*/ : string /*i*/) /*j*/ : /*k*/ void /*l*/ {}\\", Loader::Ts),\\n        (b\\"/a.ts\\", b\\"class C { public /*a*/ readonly /*b*/ x /*c*/ ! /*d*/ : number; declare /*e*/ y /*f*/ ? /*g*/ : string; }\\", Loader::Ts),\\n        (b\\"/a.ts\\", b\\"let g = (a /*1*/ ): /*2*/ number /*3*/ => a; try {} catch ( /*4*/ e /*5*/ : /*6*/ unknown /*7*/ ) {}\\", Loader::Ts),\\n    ];\\n    for &(path, text, loader) in cases {\\n        let found = lint_parse(path, loader, text, false, |parsed| describe(&parsed.sidecar.attached));\\n        println!(\\"B1 attached {:?}\\\\n{:#?}\\", bstr::BStr::new(text), found);\\n    }\\n}\\n", "type_sink_tests.rs": "\\nfn b1_dump(node: ts::Type, out: &mut Vec<String>) {\\n    out.push(format!(\\"{}[{},{})\\", node.data.kind_name(), node.start, node.end));\\n    match node.data {\\n        TypeData::TypeLiteral(literal) => {\\n            out.push(format!(\\"members<{},{}>\\", literal.members.start, literal.members.end));\\n            for member in literal.members.iter() {\\n                out.push(format!(\\"member[{},{})\\", member.start, member.end));\\n                if let MemberData::PropertySignature(property) = member.data {\\n                    if let ts::PropertyName::Computed(name) = property.name {\\n                        out.push(format!(\\"computed[{},{})\\", name.start, name.end));\\n                    }\\n                    if let Some(type_node) = property.type_node {\\n                        b1_dump(type_node, out);\\n                    }\\n                }\\n            }\\n        }\\n        TypeData::Function(function) => {\\n            out.push(format!(\\"parameters<{},{}>\\", function.parameters.start, function.parameters.end));\\n            for parameter in function.parameters.iter() {\\n                out.push(format!(\\"parameter[{},{})\\", parameter.start, parameter.end));\\n            }\\n        }\\n        TypeData::Mapped(mapped) => {\\n            let question = mapped.question_token.map(|token| (token.start, token.end));\\n            out.push(format!(\\"mapped members<{},{}> question={question:?}\\", mapped.members.start, mapped.members.end));\\n        }\\n        _ => {}\\n    }\\n}\\n\\n#[test]\\nfn zz_b1_print() {\\n    let cases: &[&\'static [u8]] = &[\\n        b\\"{ [ /*1*/ a /*2*/ + /*3*/ b /*4*/ ] /*5*/ : 1 }\\",\\n        b\\"{ [a + b /*2*/ ]: 1 }\\",\\n        b\\"(a /*1*/ = /*2*/ 1 /*3*/ + /*4*/ 2 /*5*/ , b: X /*6*/ ) /*7*/ => void\\",\\n        b\\"(a = 1 /*1*/ ) => void\\",\\n        b\\"{ a: number = /*1*/ 1 /*2*/ ; b /*3*/ : 2 }\\",\\n        b\\"{ readonly [K in /*d*/ keyof A /*e*/ ] /*f*/ -? /*g*/ : 1 /*h*/ ; /*i*/ }\\",\\n        b\\"{ [K in keyof A] ? /*g*/ : 1 }\\",\\n        b\\"import(\\\\\\"m\\\\\\", { with: { /*1*/ type /*2*/ : /*3*/ \\\\\\"json\\\\\\" /*4*/ } }) /*5*/ \\",\\n        b\\"A< /*1*/ B /*2*/ > /*3*/ | /*4*/ () => void\\",\\n    ];\\n    for &text in cases {\\n        let found = with_parser(text, |p| {\\n            p.lexer.track_all_comments(crate::lexer::TrackComments::Off);\\n            let node = p.build_type_script_type(Level::Lowest).ok()?;\\n            let mut out = Vec::new();\\n            b1_dump(node, &mut out);\\n            Some((out, p.log().errors, p.lexer.start, p.lexer.all_comments.len()))\\n        });\\n        println!(\\"B1 type_sink {:?}\\\\n{:#?}\\", bstr::BStr::new(text), found);\\n    }\\n}\\n"}')
for rel, text in parts.items():
    path = os.path.join(root, rel)
    s = open(path).read().rstrip()
    inside_mod = text.startswith("\n    #[test]")
    if inside_mod:
        assert s.endswith("}"), rel
        s = s[:-1].rstrip() + "\n" + text.rstrip()
        if not s.endswith("}\n}"):
            pass
        open(path, "w").write(s + "\n")
    else:
        open(path, "w").write(s + "\n" + text.rstrip() + "\n")
    print("ok", rel)
p = os.path.join(root, "parse/parse_skip_typescript.rs")
s = open(p).read()
pairs = [('    const LISTS: usize = 13;\n', '    const LISTS: usize = 14;\n'), ('    const TEXT: &[u8] = b"a b c d";\n', '    const TEXT: &[u8] = b"a /*1*/ b /*2*/ c /*3*/ d";\n'), ('    const ONCE: Observed = ([1; LISTS], 1, 2);\n    const TWICE: Observed = ([2; LISTS], 2, 4);\n', '    const ONCE: Observed = ([1; LISTS], 1, 8);\n    const TWICE: Observed = ([2; LISTS], 2, 16);\n'), ('        p.starts_for_parse_only = Some(StartsForParseOnly::for_lint());\n        let mut found = None;\n', '        p.starts_for_parse_only = Some(StartsForParseOnly::for_lint());\n        p.lexer.track_all_comments(crate::lexer::TrackComments::Off);\n        let mut found = None;\n'), ('            generics.type_arguments.len(),\n            generics.type_parameters.len(),\n        ];\n', '            generics.type_arguments.len(),\n            generics.type_parameters.len(),\n            p.lexer.all_comments.len(),\n        ];\n')]
for old, new in pairs:
    assert s.count(old) == 1, old[:50]
    s = s.replace(old, new)
open(p, "w").write(s)
print("ok parse/parse_skip_typescript.rs")
